void sCollision::enumSphereTriBeforeFunc(const MtSphere& s, sCollision::ScrCollisionInfo& MyCollisionInfo) {
    const f32 t0 = s.r;
    MyCollisionInfo.workVec[3].z = t0;
    MyCollisionInfo.workVec[3].y = MyCollisionInfo.workVec[3].z;
    MyCollisionInfo.workVec[3].x = MyCollisionInfo.workVec[3].y;
    MyCollisionInfo.workVec[3].pad_ = 0.0f;
    const f32 t1 = s.pos.y;
    const f32 t2 = s.pos.z;
    const f32 t3 = sCollision::EPSILON_LOOSELY;
    MyCollisionInfo.workVec[1].x = (s.pos.x - t0) - t3;
    MyCollisionInfo.workVec[1].y = (t1 - t0) - t3;
    MyCollisionInfo.workVec[1].z = (t2 - t0) - t3;
    MyCollisionInfo.workVec[1].pad_ = 0.0f;
    const f32 t4 = s.pos.y;
    const f32 t5 = s.pos.z;
    MyCollisionInfo.workVec[2].x = t3 + (t0 + s.pos.x);
    MyCollisionInfo.workVec[2].y = t3 + (t0 + t4);
    MyCollisionInfo.workVec[2].z = t3 + (t0 + t5);
    MyCollisionInfo.workVec[2].pad_ = 0.0f;
}

